-- Synthetic token issuance only; real PIN verification is not represented here.
insert into public.rw_transfer_approvals(tenant_id,id,transfer_id,action,requester,approver,request_id,transfer_snapshot,expires_at)
select h.tenant_id, case when h.id='00000000-0000-0000-0000-000000000071' then '00000000-0000-0000-0000-000000000091'::uuid else '00000000-0000-0000-0000-000000000092'::uuid end,
 h.id,'approve_transfer','00000000-0000-0000-0000-000000000031','00000000-0000-0000-0000-000000000031',case when h.id='00000000-0000-0000-0000-000000000071' then '00000000-0000-0000-0000-000000000131'::uuid else '00000000-0000-0000-0000-000000000132'::uuid end,
 jsonb_build_object('warehouse_id',h.warehouse_id,'destination_branch_id',h.destination_branch_id,'status',h.status,
 'lines',(select jsonb_agg(jsonb_build_object('sku',l.sku,'product',l.destination_product_id,'ingredient',l.destination_ingredient_id,'quantity',l.quantity) order by l.sku)
 from public.rw_warehouse_transfer_lines l where l.tenant_id=h.tenant_id and l.transfer_id=h.id)),now()+interval '1 hour'
from public.rw_warehouse_transfers h where h.tenant_id='00000000-0000-0000-0000-000000000001';
-- Explicit fixture permissions model the trusted backend, not browser access.
set role service_role;
do $$ declare result jsonb; begin
  if (not has_function_privilege('anon','public.rw_dispatch_candidate(uuid,uuid,uuid,uuid)','EXECUTE')) is distinct from true then raise exception 'ANON_RPC_GRANTED'; end if;
  if (not has_table_privilege('authenticated','public.rw_warehouse_ledger','SELECT')) is distinct from true then raise exception 'BROWSER_LEDGER_GRANTED'; end if;
  begin perform public.rw_dispatch_candidate('00000000-0000-0000-0000-000000000001','00000000-0000-0000-0000-000000000071','00000000-0000-0000-0000-000000000031','00000000-0000-0000-0000-000000000140'); raise exception 'EXPECTED_FAILURE'; exception when others then if sqlerrm <> 'APPROVAL_REQUIRED' then raise; end if; end;
  perform public.rw_transfer_decision_candidate('00000000-0000-0000-0000-000000000001','00000000-0000-0000-0000-000000000071','00000000-0000-0000-0000-000000000031','00000000-0000-0000-0000-000000000131','00000000-0000-0000-0000-000000000091','approve_transfer');
  perform public.rw_transfer_decision_candidate('00000000-0000-0000-0000-000000000001','00000000-0000-0000-0000-000000000071','00000000-0000-0000-0000-000000000031','00000000-0000-0000-0000-000000000131','00000000-0000-0000-0000-000000000091','approve_transfer');
  perform public.rw_transfer_decision_candidate('00000000-0000-0000-0000-000000000001','00000000-0000-0000-0000-000000000072','00000000-0000-0000-0000-000000000031','00000000-0000-0000-0000-000000000132','00000000-0000-0000-0000-000000000092','approve_transfer');
  if (select count(*) from public.rw_transfer_approvals where consumed_at is not null) <> 2 then raise exception 'APPROVAL_CONSUMPTION'; end if;
  perform public.rw_inbound_candidate('00000000-0000-0000-0000-000000000001','00000000-0000-0000-0000-000000000061','00000000-0000-0000-0000-000000000031','00000000-0000-0000-0000-000000000101','A',10,1001,'TEST-001');
  perform public.rw_inbound_candidate('00000000-0000-0000-0000-000000000001','00000000-0000-0000-0000-000000000061','00000000-0000-0000-0000-000000000031','00000000-0000-0000-0000-000000000101','A',10,1001,'TEST-001');
  if ((select quantity=10 and carrying_minor=1001 from public.rw_warehouse_balances where tenant_id='00000000-0000-0000-0000-000000000001' and warehouse_id='00000000-0000-0000-0000-000000000061' and sku='A')) is distinct from true then raise exception 'INBOUND_IDEMPOTENCY'; end if;
  begin perform public.rw_inbound_candidate('00000000-0000-0000-0000-000000000001','00000000-0000-0000-0000-000000000061','00000000-0000-0000-0000-000000000031','00000000-0000-0000-0000-000000000101','A',11,1001,'TEST-001'); raise exception 'EXPECTED_FAILURE'; exception when others then if sqlerrm <> 'REQUEST_CONFLICT' then raise; end if; end;
  begin perform public.rw_dispatch_candidate('00000000-0000-0000-0000-000000000001','00000000-0000-0000-0000-000000000072','00000000-0000-0000-0000-000000000031','00000000-0000-0000-0000-000000000109'); raise exception 'EXPECTED_FAILURE'; exception when others then if sqlerrm <> 'INSUFFICIENT_WAREHOUSE_STOCK' then raise; end if; end;
  if ((select quantity=10 and carrying_minor=1001 from public.rw_warehouse_balances where tenant_id='00000000-0000-0000-0000-000000000001' and warehouse_id='00000000-0000-0000-0000-000000000061' and sku='A')) is distinct from true then raise exception 'MULTILINE_ROLLBACK'; end if;
  if (not exists(select 1 from public.rw_warehouse_commands where tenant_id='00000000-0000-0000-0000-000000000001' and request_id='00000000-0000-0000-0000-000000000109')) is distinct from true then raise exception 'COMMAND_ROLLBACK'; end if;
  perform public.rw_dispatch_candidate('00000000-0000-0000-0000-000000000001','00000000-0000-0000-0000-000000000071','00000000-0000-0000-0000-000000000031','00000000-0000-0000-0000-000000000102');
  perform public.rw_dispatch_candidate('00000000-0000-0000-0000-000000000001','00000000-0000-0000-0000-000000000071','00000000-0000-0000-0000-000000000031','00000000-0000-0000-0000-000000000102');
  if ((select quantity=7 and carrying_minor=701 from public.rw_warehouse_balances where tenant_id='00000000-0000-0000-0000-000000000001' and warehouse_id='00000000-0000-0000-0000-000000000061' and sku='A')) is distinct from true then raise exception 'DISPATCH_BALANCE'; end if;
  if ((select quantity_on_hand=10 from public.ingredients where id='00000000-0000-0000-0000-000000000051')) is distinct from true then raise exception 'DISPATCH_MUST_NOT_CREDIT_BRANCH'; end if;
  result:=public.rw_receive_candidate('00000000-0000-0000-0000-000000000001','00000000-0000-0000-0000-000000000071','00000000-0000-0000-0000-000000000031','00000000-0000-0000-0000-000000000103','A',2);
  if (result->>'status'='partially_received') is distinct from true then raise exception 'PARTIAL_STATUS'; end if;
  perform public.rw_receive_candidate('00000000-0000-0000-0000-000000000001','00000000-0000-0000-0000-000000000071','00000000-0000-0000-0000-000000000031','00000000-0000-0000-0000-000000000103','A',2);
  if ((select quantity_on_hand=12 from public.ingredients where id='00000000-0000-0000-0000-000000000051')) is distinct from true then raise exception 'RECEIPT_IDEMPOTENCY'; end if;
  begin perform public.rw_receive_candidate('00000000-0000-0000-0000-000000000001','00000000-0000-0000-0000-000000000071','00000000-0000-0000-0000-000000000031','00000000-0000-0000-0000-000000000104','A',2); raise exception 'EXPECTED_FAILURE'; exception when others then if sqlerrm <> 'OVER_RECEIPT' then raise; end if; end;
  begin perform public.rw_receive_candidate('00000000-0000-0000-0000-000000000002','00000000-0000-0000-0000-000000000071','00000000-0000-0000-0000-000000000031','00000000-0000-0000-0000-000000000105','A',1); raise exception 'EXPECTED_FAILURE'; exception when others then if sqlerrm <> 'TRANSFER_NOT_FOUND' then raise; end if; end;
  result:=public.rw_receive_candidate('00000000-0000-0000-0000-000000000001','00000000-0000-0000-0000-000000000071','00000000-0000-0000-0000-000000000031','00000000-0000-0000-0000-000000000106','A',1);
  if (result->>'status'='received') is distinct from true then raise exception 'FINAL_STATUS'; end if;
  if ((select received=3 and received_minor=dispatched_minor and received_minor=300 from public.rw_warehouse_transfer_lines where tenant_id='00000000-0000-0000-0000-000000000001' and transfer_id='00000000-0000-0000-0000-000000000071' and sku='A')) is distinct from true then raise exception 'VALUE_RESIDUAL'; end if;
  if ((select sum(transit_delta)=0 and sum(transit_value_delta)=0 and sum(warehouse_value_delta+transit_value_delta+branch_value_delta)=1001 from public.rw_warehouse_ledger where tenant_id='00000000-0000-0000-0000-000000000001')) is distinct from true then raise exception 'LEDGER_RECONCILIATION'; end if;
  perform public.rw_adjust_branch_stock_candidate('00000000-0000-0000-0000-000000000001','00000000-0000-0000-0000-000000000011','00000000-0000-0000-0000-000000000041','00000000-0000-0000-0000-000000000051','00000000-0000-0000-0000-000000000031','00000000-0000-0000-0000-000000000081','00000000-0000-0000-0000-000000000111',2,'count correction');
  perform public.rw_adjust_branch_stock_candidate('00000000-0000-0000-0000-000000000001','00000000-0000-0000-0000-000000000011','00000000-0000-0000-0000-000000000041','00000000-0000-0000-0000-000000000051','00000000-0000-0000-0000-000000000031','00000000-0000-0000-0000-000000000081','00000000-0000-0000-0000-000000000111',2,'count correction');
  begin perform public.rw_adjust_branch_stock_candidate('00000000-0000-0000-0000-000000000001','00000000-0000-0000-0000-000000000011','00000000-0000-0000-0000-000000000041','00000000-0000-0000-0000-000000000051','00000000-0000-0000-0000-000000000031','00000000-0000-0000-0000-000000000081','00000000-0000-0000-0000-000000000111',3,'count correction'); raise exception 'EXPECTED_FAILURE'; exception when others then if sqlerrm <> 'REQUEST_CONFLICT' then raise; end if; end;
  begin perform public.rw_adjust_branch_stock_candidate('00000000-0000-0000-0000-000000000001','00000000-0000-0000-0000-000000000011','00000000-0000-0000-0000-000000000041','00000000-0000-0000-0000-000000000051','00000000-0000-0000-0000-000000000031','00000000-0000-0000-0000-000000000081','00000000-0000-0000-0000-000000000114',2,'count correction'); raise exception 'EXPECTED_FAILURE'; exception when others then if sqlerrm <> 'INVALID_APPROVAL' then raise; end if; end;
  begin perform public.rw_adjust_branch_stock_candidate('00000000-0000-0000-0000-000000000001','00000000-0000-0000-0000-000000000011','00000000-0000-0000-0000-000000000041','00000000-0000-0000-0000-000000000051','00000000-0000-0000-0000-000000000031','00000000-0000-0000-0000-000000000082','00000000-0000-0000-0000-000000000112',-99,'count correction'); raise exception 'EXPECTED_FAILURE'; exception when others then if sqlerrm <> 'INSUFFICIENT_STOCK' then raise; end if; end;
  if ((select consumed_at is null from public.manager_pin_approvals where id='00000000-0000-0000-0000-000000000082')) is distinct from true then raise exception 'PIN_ROLLBACK'; end if;
  begin perform public.rw_adjust_branch_stock_candidate('00000000-0000-0000-0000-000000000001','00000000-0000-0000-0000-000000000011','00000000-0000-0000-0000-000000000041','00000000-0000-0000-0000-000000000051','00000000-0000-0000-0000-000000000031','00000000-0000-0000-0000-000000000083','00000000-0000-0000-0000-000000000113',1,'count correction'); raise exception 'EXPECTED_FAILURE'; exception when others then if sqlerrm <> 'INVALID_APPROVAL' then raise; end if; end;
  if ((select quantity_on_hand=15 from public.ingredients where id='00000000-0000-0000-0000-000000000051')) is distinct from true then raise exception 'BRANCH_FINAL_QUANTITY'; end if;
end $$;
reset role;
-- A second transfer is used for the concurrent sale / receipt check.
select public.rw_inbound_candidate('00000000-0000-0000-0000-000000000001','00000000-0000-0000-0000-000000000061','00000000-0000-0000-0000-000000000031','00000000-0000-0000-0000-000000000120','B',1,100,'TEST-002');
select public.rw_dispatch_candidate('00000000-0000-0000-0000-000000000001','00000000-0000-0000-0000-000000000072','00000000-0000-0000-0000-000000000031','00000000-0000-0000-0000-000000000121');
select 'SYNTHETIC RPC ASSERTIONS PASSED';
